if(pointer.hover){let c=screenToCell(pointer.x,pointer.y);if(c&&c.x>=0&&c.x<N&&c.y>=0&&c.y<N){let p=iso(c.x,c.y),w=TILE*cam.zoom,h=TILE*.48*cam.zoom;poly([{x:p.x,y:p.y},{x:p.x+w,y:p.y+h},{x:p.x,y:p.y+2*h},{x:p.x-w,y:p.y+h}],selected?'#f7e68a77':'#fff9b944','#fffbe1')}}
}
function screenToCell(sx,sy){let x=(sx-W*.5-cam.x)/(TILE*cam.zoom),y=(sy-H*.40-cam.y)/(TILE*.48*cam.zoom);let gx=(x+y)/2,gy=(y-x)/2;return {x:Math.round(gx),y:Math.round(gy)}}
const pointer={x:0,y:0,hover:false,down:false,moved:false,lastX:0,lastY:0};
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function showNote(msg){const e=document.getElementById('statusNote');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1700)}
function fmt(n){return '$ '+Math.floor(n).toLocaleString('pt-BR')}
const state={money:8500,pop:12,happy:74,tech:14,culture:10,tax:1,services:1,gameOver:false};
function level(){return state.tech>=850?5:state.tech>=500?4:state.tech>=250?3:state.tech>=100?2:1}
function levelName(l=level()){return ['','VILA','CIDADE PEQUENA','CIDADE MÉDIA','METRÓPOLE','MEGACIDADE'][l]}
function updateUI(){document.getElementById('money').textContent=fmt(state.money);document.getElementById('pop').textContent=state.pop.toLocaleString('pt-BR');document.getElementById('happiness').textContent=Math.round(state.happy)+'%';document.getElementById('level').textContent=`NÍVEL ${level()} · ${levelName()}`;let points=[0,100,250,500,850][level()];document.getElementById('techFill').style.width=Math.min(100,state.tech/850*100)+'%';document.getElementById('techGoal').textContent=level()<5?`Próximo nível: ${points} pts`:'Tecnologia máxima ✦';let mood=state.happy>72?['😇','Bom governante']:state.happy>42?['😐','Governante neutro']:['😈','Governante rígido'];document.getElementById('moodFace').textContent=mood[0];document.getElementById('moodText').textContent=mood[1];document.getElementById('dateTag').textContent=`ANO ${String(year).padStart(2,'0')} · ${['PRIMAVERA','VERÃO','OUTONO','INVERNO'][Math.floor((month-1)/3)]} · MÊS ${month}`;draw()}
function selectTool(t){selected=t;document.querySelectorAll('.tool').forEach(e=>e.classList.toggle('active',e.dataset.id===t));let o=tools.find(a=>a[0]===t);document.getElementById('costHint').innerHTML=t?`Custo: <strong>${o[3]?'$ '+o[3]:'livre'}</strong> · ${o[2]}`:'Selecione uma construção';showNote(t==='bulldoze'?'Toque em algo para demolir':'Toque no terreno para construir')}
function counts(type){let n=0;for(let row of grid)for(let o of row)if(o&&o.type===type)n++;return n}
function placeAt(x,y){if(!selected||x<0||y<0||x>=N||y>=N)return;let item=tools.find(a=>a[0]===selected);if(selected==='bulldoze'){if(!grid[y][x])return toast('Nada para demolir aqui');if(grid[y][x].type==='trailer')return toast('O trailer do prefeito fica!');grid[y][x]=null;state.money+=30;toast('Terreno liberado · +$30');updateUI();return}
if(grid[y][x])return toast('Esse espaço já está ocupado');if(state.money<item[3]&&mode!=='sandbox')return toast('Tesouro insuficiente! Ajuste impostos ou peça empréstimo.');if(mode!=='sandbox')state.money-=item[3];grid[y][x]={type:selected,level:level()};if(['res','com','ind'].includes(selected)){if(counts('road')===0)return toast('Construa uma estrada primeiro!');}if(selected==='road')toast('Estrada pavimentada · conexão pronta');else toast(`${item[2]} construído!`);updateUI()}
function pointerDown(e){if(e.target.closest('button,.overlay,.build-dock,.topbar,.floating,.techbar,.mood,.day-tag'))return;pointer.down=true;pointer.moved=false;pointer.lastX=e.clientX;pointer.lastY=e.clientY;pointer.x=e.clientX;pointer.y=e.clientY;canvas.setPointerCapture?.(e.pointerId)}
function pointerMove(e){pointer.x=e.clientX;pointer.y=e.clientY;pointer.hover=true;if(pointer.down){let dx=e.clientX-pointer.lastX,dy=e.clientY-pointer.lastY;if(Math.abs(dx)+Math.abs(dy)>4)pointer.moved=true;if(pointer.moved){cam.x+=dx;cam.y+=dy}pointer.lastX=e.clientX;pointer.lastY=e.clientY}draw()}
function pointerUp(e){if(!pointer.down)return;pointer.down=false;if(!pointer.moved){let c=screenToCell(e.clientX,e.clientY);placeAt(c.x,c.y)}draw()}
canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',()=>pointer.down=false);canvas.addEventListener('pointerleave',()=>{pointer.hover=false;draw()});canvas.addEventListener('wheel',e=>{cam.zoom=Math.max(.65,Math.min(1.7,cam.zoom*(e.deltaY<0?1.1:.9)));draw()},{passive:true});
function drawTools(){let el=document.getElementById('tools');el.innerHTML=tools.map(([id,icon,label,cost])=>`<button class="tool" data-id="${id}"><span class="emoji">${icon}</span><span>${label}</span></button>`).join('');el.querySelectorAll('.tool').forEach(b=>b.onclick=()=>selectTool(b.dataset.id))}
drawTools();
function addPost(text){posts.unshift({name:names[Math.floor(Math.random()*names.length)],avatar:avatars[Math.floor(Math.random()*avatars.length)],text,time:'agora'});if(posts.length>12)posts.pop();postUnread=true;document.getElementById('chatterBtn').classList.add('has-new')}

