function monthly(){if(paused||!started||state.gameOver)return;month++;if(month>12){month=1;year++}let residents=counts('res')+counts('trailer'),com=counts('com'),ind=counts('ind'),park=counts('park'),school=counts('school'),service=counts('police')+counts('power')+counts('water');let gross=Math.round(state.pop*(20+state.tax*7)+com*90+ind*100),upkeep=120+service*65+park*16+school*55+state.pop*7+Math.ceil(debt*.04);let net=gross-upkeep;if(mode==='sandbox')net=0;state.money+=net;debt=Math.max(0,debt-Math.floor(debt*.025));state.pop=Math.max(0,12+residents*36+com*5+Math.floor(state.tech/25));state.tech=Math.min(1000,state.tech+school*12+park*7+Math.max(0,service)*2+Math.floor(state.happy/22));state.culture+=park*3+school*5;traffic=Math.min(100,Math.max(5,state.pop/5+counts('road')*2-counts('road')*2.7));let serviceScore=Math.min(35,service*8+park*5+school*4),taxHit=(state.tax-1)*12;state.happy=Math.max(5,Math.min(99,Math.round(60+serviceScore-taxHit+Math.min(14,(state.tech/80))-Math.max(0,state.pop/70-counts('road')*3))));if(state.money<0)negativeMonths++;else negativeMonths=0;if(negativeMonths>=3){endGame(false);return}if(mode==='campaign'&&state.pop>=5000&&level()===5){endGame(true);return}if(Math.random()<.72){let msgs=state.happy<35?['Imposto alto e a rua segue esburacada. Que gestão...','A conta não fecha e nem a prefeitura responde.','Sem serviço, mas o carnê chegou pontual.']:traffic>65?['Trânsito parado na avenida principal!','Minha carroça virou parte do congestionamento.']:counts('power')===0?['Falta energia no meu trailer! Alguém avisa a prefeitura?']:counts('park')===0?['Um parquinho nessa cidade cairia bem 🌱','Só concreto e poeira por aqui...']:['A praça nova ficou uma graça! 🌳','Minha rua ganhou vida, bom trabalho!','Cidade pequena, sonhos enormes ✨'];addPost(msgs[Math.floor(Math.random()*msgs.length)])}updateUI();if(net>=0)toast(`${net>=0?'+':''}${fmt(net)} neste mês · caixa atualizado`);else toast(`${fmt(net)} neste mês · despesas da cidade`)}
let monthTimer=setInterval(monthly,22000);
function openModal(html){let o=document.getElementById('overlay');o.innerHTML=html;o.style.display='grid'}function closeModal(){document.getElementById('overlay').style.display='none'}
function menu(){paused=true;openModal(`<div class="modal"><div class="modal-kicker">✦ UM NOVO COMEÇO · 16-BIT CITY BUILDER</div><h1>PEQUENA<br>FORTUNA<span style="color:#e2a35a">.</span></h1><p>Um terreno, um trailer e uma promessa duvidosa. Construa uma cidade que dê certo — ou pelo menos que pareça dar.</p><div class="hero-art"><canvas id="heroCanvas" width="500" height="170"></canvas></div><div class="section-title">Escolha seu jeito de governar</div><div class="mode-grid"><button class="mode" data-mode="campaign"><span class="mode-icon">🏛️</span><strong>Campanha</strong><small>Metas, pressão presidencial e um prêmio misterioso.</small></button><button class="mode" data-mode="classic"><span class="mode-icon">🌇</span><strong>Clássico</strong><small>Cresça sem fim. O Presidente não dá palpites.</small></button><button class="mode" data-mode="sandbox"><span class="mode-icon">🪄</span><strong>Sandbox</strong><small>Dinheiro infinito e liberdade total.</small></button></div><p style="font-size:10px;margin:2px 0 0">👆 Tudo por toque · arraste para explorar · zoom com os botões</p></div>`);drawHero();document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>begin(b.dataset.mode))}
function drawHero(){let c=document.getElementById('heroCanvas');if(!c)return;let q=c.getContext('2d');q.imageSmoothingEnabled=false;q.fillStyle='#badbd3';q.fillRect(0,0,500,170);q.fillStyle='#8eb997';q.fillRect(0,114,500,56);q.fillStyle='#91b78c';q.fillRect(0,96,500,20);q.fillStyle='#ffefb5';q.fillRect(405,22,44,44);for(let i=0;i<9;i++){q.fillStyle=['#7da96c','#87b777','#6c9e6d'][i%3];q.fillRect(i*63,100+(i%2)*8,42,45);q.fillStyle='#f2d89c';q.fillRect(i*63+10,110,7,8);q.fillRect(i*63+25,110,7,8)}q.fillStyle='#71806e';q.fillRect(0,141,500,13);q.fillStyle='#e3d8aa';for(let i=0;i<12;i++)q.fillRect(i*46,147,20,2);q.fillStyle='#c1895c';q.fillRect(211,82,38,33);q.fillStyle='#e9c895';q.fillRect(218,72,24,17);q.fillStyle='#648d82';q.fillRect(218,91,9,9);q.fillRect(233,91,9,9);q.fillStyle='#365449';q.font='bold 12px monospace';q.fillText('TERRENO À VENDA · 1 PREFEITO INCLUSO',20,24)}
function begin(m){mode=m;started=true;paused=false;month=1;year=1;debt=0;negativeMonths=0;state.money=m==='sandbox'?999999:8500;state.pop=12;state.happy=74;state.tech=14;initMap();cam={x:0,y:0,zoom:1};closeModal();if(m==='campaign')prologue();else{toast(m==='sandbox'?'Modo Sandbox: tesouro infinito!':'Modo Clássico: construa sem limites.');updateUI()}}
function prologue(){paused=true;openModal(`<div class="modal"><div class="modal-kicker">PRÓLOGO · UM ACORDO MUITO SUSPEITO</div><div class="president-card"><div class="president">😎</div><div class="quote"><b>Presidente Dourado</b><br>“Ganhei esse terreno numa aposta de golfe e não tenho onde estacionar o iate. Faça uma metrópole lucrativa e terá um prêmio misterioso!”</div></div><h2>Seu mandato começa agora.</h2><p>Construa estradas, atraia moradores e invista em serviços. Alcance <b>5.000 habitantes</b> e a tecnologia máxima sem falir — nem irritar o Presidente. Um saldo negativo por 3 meses acaba com seu mandato.</p><div class="row"><button class="secondary" id="later">Pular prólogo</button><button class="primary" id="startCampaign">Assinar a escritura →</button></div></div>`);document.getElementById('later').onclick=()=>{closeModal();paused=false};document.getElementById('startCampaign').onclick=()=>{closeModal();paused=false;addPost('Uma cidade novinha em folha! Será que vem uma praça?');updateUI()}}

