// --- Áudio retrô 16-bit, totalmente sintetizado pelo Web Audio ---
let audioCtx=null,master=null,musicGain=null,fxGain=null,musicMuted=false,audioReady=false,musicTimer=null,musicStep=0;
function initAudio(){
 if(audioReady)return audioCtx.resume&&audioCtx.resume();
 const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
 audioCtx=new AC();master=audioCtx.createGain();master.gain.value=.55;master.connect(audioCtx.destination);
 musicGain=audioCtx.createGain();musicGain.gain.value=.13;musicGain.connect(master);
 fxGain=audioCtx.createGain();fxGain.gain.value=.38;fxGain.connect(master);
 audioReady=true;startChiptune();
}
function tone(freq,duration=.08,type='square',gain=.12,slide=0,delay=0,output=fxGain){
 if(!audioReady||musicMuted||!output)return;
 const t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();
 o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),t+duration);
 g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+duration);
 o.connect(g);g.connect(output);o.start(t);o.stop(t+duration+.02);
}
