function sfxChatter(){tone(660,.06,'square',.07,150);tone(880,.08,'square',.06,90,.08)}
function startChiptune(){
 if(musicTimer)return;const bass=[110,110,147,147,130.81,130.81,98,98];
 const lead=[659.25,783.99,880,783.99,659.25,587.33,523.25,587.33,659.25,783.99,880,987.77,880,783.99,659.25,587.33];
 musicTimer=setInterval(()=>{
  if(!audioReady||musicMuted||paused||document.hidden)return;
  const i=musicStep%16,t=(musicStep%4);
  tone(lead[i],.16,'square',.018,0,0,musicGain);
