  musicStep++;
 },220);
}
function setMuted(muted){
 musicMuted=muted;
 const b=document.getElementById('soundBtn');if(b)b.textContent=muted?'🔇':'🔊';b?.setAttribute('aria-label',muted?'Ativar música e efeitos':'Mutar música e efeitos');
